'use strict';
/**
 * Boyfriend Day family — binary assets carried as data.
 *
 * The share cards (og.jpg) and Meri Duniya's wax seal are binaries, and the
 * text-only git API this repo is deployed through cannot carry them — the
 * same reason lib/brand-assets.js exists. ensureFamilyAssets() writes each
 * file under public/ at boot when it is missing or its bytes differ (sha256),
 * and never touches anything else.
 */
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

const ASSETS = [
  {
    path: 'meri-duniya/og.jpg',
    sha256: '92526b67e41d1341171bb059e5ae72fef7e1eba6349514b0023c733594c9a077',
    data: '',
  },
  {
    path: 'meri-duniya/wax-seal.webp',
    sha256: 'bb2da22373e641241b44a53bc77373190fc748e2bf94023773dd528347f87d1a',
    data: '',
  },
  {
    path: 'khulta/og.jpg',
    sha256: '27b8525d83d49f14fe958c5ed0ad923c03f7907da2fba34ef80370b7a1372b2c',
    data: '',
  },
  {
    path: 'aakhri-sawaal/og.jpg',
    sha256: '72fb240c1928ffe50695539184ee07d19ff08e62efd5e4627f1810dbc14d4096',
    data: '',
  },
];

function ensureFamilyAssets() {
  const root = path.join(__dirname, '..', '..', 'public');
  const written = [];
  for (const a of ASSETS) {
    const file = path.join(root, a.path);
    let ok = false;
    try { ok = crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex') === a.sha256; } catch { ok = false; }
    if (ok) continue;
    try {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, Buffer.from(a.data, 'base64'));
      written.push(a.path);
    } catch (e) {
      console.error('[bfday] could not write asset ' + a.path + ': ' + e.message);
    }
  }
  return written;
}

module.exports = { ensureFamilyAssets, ASSETS };
